# Export code-native outline icons as independent scalable assets.
src=(ROOT/'prototype/app.js').read_text()
match=re.search(r'const icons=\{(.*?)\};',src,re.S)
parts=re.findall(r"(\w+):'([^']+)'",match.group(1))
(ROOT/'assets/icons').mkdir(exist_ok=True)
for name,d in parts:
 (ROOT/'assets/icons'/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="{d}"/></svg>')
